INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Egg Venture', 'One of the more "kid-friendly" animated gun-shooting games. Players use an optical gun to shoot at the "bad eggs" while avoiding shooting the "good guy eggs". Players advance stage by stage to different levels by shooting a certain number of targets.' FROM games WHERE igdb_id = 40302 ON CONFLICT (game_id, language_code) DO NOTHING;
