INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Linley Henzell''s Dungeon Crawl', 'Linley''s Dungeon Crawl (or just Dungeon Crawl or Crawl) was a roguelike computer game originally programmed by Linley Henzell in 1995, and first released to the general public on October 2, 1997. The game had a quirky license based on Bison''s license and the NetHack License; Stone Soup has contacted every past contributor and relicensed to GPL-2.0-or-later.' FROM games WHERE igdb_id = 84198 ON CONFLICT (game_id, language_code) DO NOTHING;
