INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'BS F-Zero Grand Prix 2: Practice', 'BS F-Zero Grand Prix 2 is the direct sequel to the original F-Zero game released for the Super Famicom via the Satellaview. Two versions were released - a non-SoundLink game and a SoundLink game. The original non-SoundLink version was released as BSF-Zero 2 Practice (BS F-ZERO 2 プラクティス) on June 1, 1997 (although the title screen remained the same). It contained the four courses first seen throughout BS F-Zero Grand Prix (a Satellaview remake of the original), along with a new course called Mute City IV.' FROM games WHERE igdb_id = 38348 ON CONFLICT (game_id, language_code) DO NOTHING;
