INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Digimon', 'The Digital Monster is a digital pet created by WiZ and Bandai that spawned the Digimon franchise. It was released by Bandai on June 26, 1997 in Japan and on December 5, 1997 in North America. This pet was a masculine counterpart to the Tamagotchi, which was deemed more appropriate for girls. It was similar to earlier virtual pets with the distinctions of being a fighting pet that could connect with others like it.' FROM games WHERE igdb_id = 194324 ON CONFLICT (game_id, language_code) DO NOTHING;
