INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Castelo Rá-Tim-Bum', 'Castelo Rá-Tim-Bum is an action-adventure game based on the popular educational Brazilian TV series with the same name. The player can chose to play either Pedro or Biba to search for the ingredients through five levels. Each level involves some platforming and minor puzzle solving elements, like jumping over the right sequence of platforms, or finding food inside the kitchen''s drawers in the right order.' FROM games WHERE igdb_id = 84302 ON CONFLICT (game_id, language_code) DO NOTHING;
