INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jimmy Johnson''s VR Football ''98', 'As Interplay''s first PlayStation football game under the VR Sports label, Jimmy Johnson''s VR Football ''98 offers both NFL and NFLPA licenses for real teams and players. Choose from 30 NFL teams with rosters reflecting the 1997 season, five of the greatest teams from the ''70s, five from the ''80s, five from the ''60s, or five All-Pro Teams from 1996 and 1997. 
