INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sierra Pro Pilot 98: The Complete Flight Simulator', 'This is the first edition in the Pro Pilot civilian flight simulation series. The scenery is North America and Europe, and both VFR/IFR can be used with AI Air traffic controllers. The included aircraft are: Cessna Skyhawk 172P, 172R, CitationJet 525, Beechcraft Bonanza V35, Baron B58, and Super King Air B200.' FROM games WHERE igdb_id = 62276 ON CONFLICT (game_id, language_code) DO NOTHING;
