INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disney''s Ready to Read with Pooh', 'Literary bear and animated film star Winnie the Pooh sets the stage in this educational game from Disney, as he drifts down to the ground via balloon to land outside a Treehouse which becomes the home screen. Gopher provides a mailbox with the player''s name on it, and Pooh sets down a honey pot which becomes the options screen. On returning to the Treehouse from elsewhere in the Wood, the personalized mailbox may contain messages from game characters who will read the letter out loud when the mailbox is clicked on.' FROM games WHERE igdb_id = 20390 ON CONFLICT (game_id, language_code) DO NOTHING;
