INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'F-1 Grand Prix 1996: Team Unei Simulation', 'F1 grand Prix 1996 Team Unei Simulation puts the player in the role of a F1 team manager the player can choose the manager nationality): The player can choose the sponsor, talk with his team mechanics to design his own car (choosing all the car parts), hire the team drivers, test the F1 car before each race and after that compete in all the 1996 F1 grand prix and guide the team to the victory using your own strategy (but the player can''t drive the cars).' FROM games WHERE igdb_id = 382916 ON CONFLICT (game_id, language_code) DO NOTHING;
