INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Eraser: Turnabout', 'Eraser Turnabout is a predominantly action game with some puzzle-solving, featuring pre-rendered action scenes and a lot of recorded full screen video. You play the role of John Krueger on a hectic mission to shut down a conspiracy in a few hours that threatens the free world and to stop a terrorist strike. Along the way you get to shoot a lot of assassins, solve puzzles and clues. There are a few additional characters that accompany you on the way, but mostly you will be on your own.' FROM games WHERE igdb_id = 64237 ON CONFLICT (game_id, language_code) DO NOTHING;
