INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disney''s The Hunchback of Notre Dame', 'Disney''s The Hunchback of Notre Dame is an Action game and a mini games collection based on the Disney movie of the same name. It''s essentially the same game as the PC version, but features two new mini games ("Catch the Fool" and "Picture Puzzle"). In turn, the mini games "Le Food Fight" and "Inside Outwords" were removed.' FROM games WHERE igdb_id = 48992 ON CONFLICT (game_id, language_code) DO NOTHING;
