INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '3x3 Eyes: Tenrin-ou Genmu', 'The game is a puzzle-less adventure in Japanese fashion, which plays like an interactive anime. The game contains many animated cutscenes, and the locations of the game are still shots in anime style. Unlike most Japanese adventures, the player interacts with the game world not by choosing commands from a menu, but by moving a cursor on the screen. Once the cursor is placed on an object possible to interact with, it is highlighted with an additional command, such as "look", "talk", etc.' FROM games WHERE igdb_id = 73304 ON CONFLICT (game_id, language_code) DO NOTHING;
