INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('imperialism', 14435, '1997-08-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2tx2.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar85l.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Imperialism', 'In Imperialism you rule one of the Great Powers in a world modeled on the real world of the nineteenth century. As the game begins, your country and the other Great Powers begin a period of rapid economic, military, and social advancement due to the onset of the Industrial Revolution. You must first harness these historic forces to develop your own country, and then use your new found wealth and resources to compete successfully with the other Great Powers in the realms of diplomacy, trade, and war. Only one Great Power can establish the pre-eminent Empire in the world.' FROM games WHERE igdb_id = 14435 ON CONFLICT (game_id, language_code) DO NOTHING;
