INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Excalibur: Morgana''s Revenge', 'The game''s story expands on the legend of King Arthur and involves the Sword of Power, Excalibur; the wizard Merlin; the sorceress Morgana; and the future United Earth Federation (UEF). The story takes places across three time periods.[4] According to the game, Morgana uses the Charm of Making to imprison Merlin in ice during the fall of Arthur''s kingdom. Merlin then disappears from Camelot in an electrical storm during the battle for Camelot.' FROM games WHERE igdb_id = 150231 ON CONFLICT (game_id, language_code) DO NOTHING;
