INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Meltylancer Re-inforce', 'MeltyLancer: Re-inforce is a sequel to MeltyLancer: Ginga Shoujo Keisatsu 2086 and takes place two years after, meaning in 2088. The core gameplay consists of isometric turn-based combat on one hand, and on visual novel and dating simulation style interaction with other characters. The player plays a young rookie transferred to a GPO (Galactic Police Organization) unit under Sylvie, the heroine from the previous game. The goal is to learn from the best and uphold the law.' FROM games WHERE igdb_id = 60976 ON CONFLICT (game_id, language_code) DO NOTHING;
