INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('disneys-ready-for-math-with-pooh', 85959, '1997-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1wcu.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc7itn.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disney''s Ready For Math With Pooh', 'When Pooh floats down to land in the Hundred Acre Wood in Disney''s Ready for Math With Pooh, he comes to earth in what will become a garden as the game progresses. The player signs in on a wheelbarrow and chooses a path from the three directions given - in each of these places he''ll meet Pooh''s friends; Piglet, Owl, Tigger, Eeyore, Roo, and Pooh himself, and play games designed to exercise his math skills at one of three levels.
