INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SatellaWalker', 'SatellaWalker (also known by its shorthand, SW) is a Downloadable 2-part Soundlink game for the Satellaview that was broadcast between June 29, 1997 and January 2, 1998. It is a pseudo-RPG adventure game that takes place in the world of the BS-X BIOS. The player''s avatar character (the same one from BS-X) walks around the Town Whose Name has been Stolen accomplishing various activities and collecting various items.' FROM games WHERE igdb_id = 134468 ON CONFLICT (game_id, language_code) DO NOTHING;
