INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mars 3D', 'A first-person 3D shooter/vehicular action game set on a colonized Mars. Players pilot armed rovers and on-foot vehicles through hostile alien-infested environments to complete mission objectives, rescue survivors, and retrieve resources. Features fast-paced combat, destructible terrain elements, and polygonal graphics optimized for DOS PCs.' FROM games WHERE igdb_id = 159197 ON CONFLICT (game_id, language_code) DO NOTHING;
