INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disney''s Hercules Action Game', 'Disney''s Hercules Action Game is a platform game mainly two-dimensional, although in many missions the player can walk to other planes via pathways or stairs. There are ten levels and three difficulty modes: Beginner, Medium, and Herculean. Hercules can jump, grab ledges, swing on poles, and jump while running. He has a variety of attack moves at his disposal.' FROM games WHERE igdb_id = 9814 ON CONFLICT (game_id, language_code) DO NOTHING;
