INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crime Crackers 2', 'Crime Crackers 2 is the sequel to Crime Crackers, and is again a first-person action game in a similar style. It takes place two years after the original, following a team of Crackers who got into the business after being inspired by Team Pink Dolphin, the heroes of the first game. Just like the previous title, the player must explore each area, defeating enemies and collecting items until they find and defeat the boss.' FROM games WHERE igdb_id = 65344 ON CONFLICT (game_id, language_code) DO NOTHING;
