INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fighter Ace', 'Do YOU have what it takes?! Killer or cannon fodder, Binky? Strap one of WW II''s mightiest fighters to your virtual backside and prepare for TOTAL WAR! Microsoft Fighter Ace is a premium, subscription-only game that hurls YOU into the cockpit in a massively multiplayer aerial melee guaranteed to get your heart pounding and adrenaline squirting through your veins.' FROM games WHERE igdb_id = 209427 ON CONFLICT (game_id, language_code) DO NOTHING;
