INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'You Don''t Know Jack Television', 'If you thought all those hours of watching TV were good for nothing, then You Don''t Know Jack… Television! With more categories than your local cable provider, You Don''t Know Jack Television spans over 50 years of boob-tube trivia, from Ralph Kramden to the guy on “King of Queens” who looks like Ralph Kramden. So set down the remote and put your recliner in the upright and locked position… it''s You Don''t Know Jack Television' FROM games WHERE igdb_id = 16787 ON CONFLICT (game_id, language_code) DO NOTHING;
