INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Intelligent Qube', 'Intelligent Qube is a puzzle game for the PlayStation. In the game, the player controls a character who must run around a platform made of cubes, clearing certain cubes as they approach. Cubes are "cleared" by marking a spot on the stage, waiting for the cube to roll on top of it, and then deactivating the marked spot.' FROM games WHERE igdb_id = 4126 ON CONFLICT (game_id, language_code) DO NOTHING;
