INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kunoichi Torimonocho', 'Kunoichi Torimonochō (Kunoichi Detective Story) is a Japanese-style adventure game. Take the role of Ran and travel around Edo, interact with a variety of colorful characters, play numerous minigames, and attempt to train Ran into a proper Kunoichi. There are multiple endings depending upon your choices and performance through the game.' FROM games WHERE igdb_id = 123577 ON CONFLICT (game_id, language_code) DO NOTHING;
