INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dark Rift', 'Dark Rift delivers hyper-active 3D fighting with a sci-fi theme! Compete against eight exotic and powerful characters and two very large bosses. Motion captured character animations enhance the realism. The arsenal includes multiple-hit combos, back-crunching grabs, juggles, projectiles, and punishing special moves. Tune into individual character stereo sound tracking. Fight in Tournament, 2-Player or Training modes.' FROM games WHERE igdb_id = 3468 ON CONFLICT (game_id, language_code) DO NOTHING;
