INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'A2 Racer', 'A game where you can race over the most infamous freeway in the Netherlands: the A2. In A2 Racer, you join a band of illegal streetracers whose only goal is to get from A to B as fast as possible. You must weave your way through the regular traffic on the A2, grabbing power-ups like fuel, money and time and making sure the police can''t catch you. Be sure to be #1 in this game, for the rest are considered losers.' FROM games WHERE igdb_id = 92803 ON CONFLICT (game_id, language_code) DO NOTHING;
