INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Le Mans 24', 'Le Mans 24 (ル・マン 24) is a Sega Model 3 arcade game by Sega, based on the real life endurance race of the same name and licensed by its organisers, Automobile Club de l''Ouest. It is unrelated to Le Mans 24 Hours for the Sega Dreamcast.
