INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Microsoft Flight Simulator 98', 'Microsoft Flight Simulator ''98 is the sequel to the popular Microsoft Flight Simulator ''95, with many improvement, including the ability to fly helicopters and aerial stunt plane and more. Terrain maps are plotted from actual NASA satellite photos, and you can even enter actual GPS coordinates and that will take you directly over a precise area.' FROM games WHERE igdb_id = 3360 ON CONFLICT (game_id, language_code) DO NOTHING;
