INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Eojjeonji Joeun Iri Saenggil Geot Gateun Jeonyeok', 'Eojjeonji Joheun Il-i Saenggil Geot Gateun Jeonyeok (which roughly translates to "A Night Where Good Things Are Bound to Happen") is a Korean-made beat-em-up based on the comic book by Myung Jin Lee. The protagonist of the game is a rebellious teenager named Namgoong Gunn. On the way to his new school, where he hopes to forget his rather violent past, he spots a beautiful girl, and immediately afterwards his wallet gets stolen. Following the thief, Gunn gets involved in a struggle against a powerful criminal syndicate.' FROM games WHERE igdb_id = 213055 ON CONFLICT (game_id, language_code) DO NOTHING;
