INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Top Gear Rally', 'Top Gear Rally is a 1997 racing video game developed by Boss Game Studios and released for the Nintendo 64. A follow-up to Kemco''s original Top Gear game, it features a championship mode where a single player must complete six seasons of two to four races, as well as a multiplayer mode where two players may compete against each other via a split-screen display.' FROM games WHERE igdb_id = 3617 ON CONFLICT (game_id, language_code) DO NOTHING;
