INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'R no Shosai', 'R no Shosai is a downloadable 2-part Soundlink game for the Satellaview that was broadcast in at least 2 distinct runs between June 1, 1997 and February 21, 1998. The game is a mystery sound novel presented in two acts. It envolves an unknown man named "R" and the letter/cassette a newspaper reporter receives in the mail. The voice actor was Koyama Takeshi. It received a sequel, also on Satellaview.' FROM games WHERE igdb_id = 93531 ON CONFLICT (game_id, language_code) DO NOTHING;
