INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Lost World: Jurassic Park', 'The Lost World: Jurassic Park is an action-adventure video game developed by DreamWorks Interactive and Appaloosa Interactive, and published by Electronic Arts and Sega for the Sony PlayStation and Sega Saturn, respectively, in 1997. The Lost World: Jurassic Park is based on the film of the same name, which in turn is based on the novel by Michael Crichton. In 1998 a special edition of the game was released for the Sony PlayStation as a Greatest Hits title and featured several modifications to the gameplay.' FROM games WHERE igdb_id = 19536 ON CONFLICT (game_id, language_code) DO NOTHING;
