INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Excalibur 2555 A.D.', 'Taking cues from already established hits such as Tomb Raider, Excalibur 2555 A.D. takes place from a third-person perspective which allows for a better flow of gameplay. As you advance through the mythical world of ancient England, you encounter various types of items and weapons, all of which will aid you in your quest for Excalibur.' FROM games WHERE igdb_id = 15514 ON CONFLICT (game_id, language_code) DO NOTHING;
