INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('fire', 231720, '1997-02-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co618n.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar22zz.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fire', 'Mario and Luigi attempt to catch Toads, Yoshis, and Donkey Kong Jrs. after they jump out the window of Princess Peach''s burning castle. The catch is that different characters fall at different speeds: Toads bounce the highest, while Donkey Kong Jrs. bounce the lowest. Yoshi Eggs also appear and contain either a Bob-omb or a Moon (a Super Star in the first game); the eggs break open when they are caught or hit the ground. The player receives two points for catching an egg. If a Bob-omb reaches the carriage, everyone, including the Mario Bros., runs away as the carriage explodes, and the player gets a miss. If the Mario Bros. catch a Moon, the player receives five points. At 200, 500, and 700 points, Peach appears and blows a kiss, sending out a heart for Mario or Luigi to catch to remove a miss. Music is also featured in this version, with the tempo changing depending on the speed of the game.' FROM games WHERE igdb_id = 231720 ON CONFLICT (game_id, language_code) DO NOTHING;
