INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shining Force III', 'Shining Force III is a fantasy turn-based tactics role-playing video game designed for the Sega Saturn by Camelot Software Planning. It is a continuation of the Shining series. Comprising three separate but overlapping storylines, the Japanese version of Shining Force III was released in three volumes, known as: "Scenario 1 - God Warrior of the Kingdom", "Scenario 2 - Target: Child of God", and "Scenario 3 - "Bulzome Rising".
