INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hover Racing', 'Hover Racing was created by a small team of university students led by designer Tomokazu Sato and primary composer Hiroaki Ohmori between April and November of 1997, a concise but polished clone of futuristic racing games like F-Zero X and Wipeout. The core gameplay consists of 3 Grand Prix with 3 tracks each, as well your usual practice and time attack modes.' FROM games WHERE igdb_id = 92710 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 92710 AND ge.slug = 'racing' ON CONFLICT DO NOTHING;
