INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Take No Prisoners', 'Take No Prisoners is a 1997 game set in a post-apocalyptic Texas; with the main character, Slade, given the mission to retrieve an object from the center of a small town. Slade, having to battle past the cities violent inhabitants, manages to retrive the object and escape the city alive.' FROM games WHERE igdb_id = 8696 ON CONFLICT (game_id, language_code) DO NOTHING;
