INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Advanced World War Sen-nen Teikoku no Koubou: Last of the Millennium', 'Advanced World War Sennen Teikoku no Koubou: Last of the Millennium is an RTS game on Sega Saturn released by Sega in 1997. The goal of the game is to fight through World War II (European front) by manipulating Nazi German forces.' FROM games WHERE igdb_id = 45448 ON CONFLICT (game_id, language_code) DO NOTHING;
