INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Samurai Shodown 64', 'Samurai Shodown 64 is a 3D fighting game produced by SNK for the Hyper Neo Geo 64 system in 1997. It is the fifth game in Samurai Shodown series and the seventh of the official chronology. It was SNK''s first attempt to bring one of their franchises into the 3D realm. It received relatively no distribution outside of Japan, and is thus not very well known. After having released two semi-prequels in the Samurai Shodown series on the 16-bit Neo Geo, SNK announced that they would be producing a new arcade hardware platform, this one 64-bit and with extensive 3D capabilities.' FROM games WHERE igdb_id = 19990 ON CONFLICT (game_id, language_code) DO NOTHING;
