INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Reading Blaster: Ages 9-12', 'Reading Blaster: Ages 9-12 is an educational point-and-click adventure game. Use your reading comprehension skills to help Rave rescue the missing people. Find the main ideas, detect important details and draw conclusions to unravel the mystery! Master over 20 essential skills with over 75 unique mystery stories that will stimulate your imagination. Three levels of difficulty offer progressive learning challenges, and comprehensive content prepares you for standardized tests.' FROM games WHERE igdb_id = 191530 ON CONFLICT (game_id, language_code) DO NOTHING;
