INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Marvel Super Heroes vs. Street Fighter', 'Now you can choose your favorite heroes from the worlds of Street Fighter and Marvel Super Heroes to face off in a head-to-head battle for supremacy. Dive into the action to perform outrageous moves and link together amazing Chain Combos... then delight in their devastating results! Marvel Super Heroes vs. Street Fighter combines two incredible universes to create an entirely new legend of heroic proportions.' FROM games WHERE igdb_id = 8245 ON CONFLICT (game_id, language_code) DO NOTHING;
