INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shinseiki Evangelion: Koutetsu no Girlfriend', 'Neon Genesis Evangelion: Girlfriend of Steel, also known as Neon Genesis Evangelion: Iron Maiden, is a video game based on the Gainax anime/manga series Neon Genesis Evangelion, released officially only in Japan for the PlayStation, Sega Saturn, PlayStation 2, PSP, Windows (PC), and Macintosh. On January 20, 2005 a sequel was released titled "Neon Genesis Evangelion: Girlfriend of Steel 2nd" for the Playstation 2, and while it does feature much of the cast of the original game, the story is unrelated to the original''s.' FROM games WHERE igdb_id = 23953 ON CONFLICT (game_id, language_code) DO NOTHING;
