INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('yu-no-a-girl-who-chants-love-at-the-bound-of-this-world', 201228, '1997-12-04', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4r34.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sch02f.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'YU-NO: A Girl Who Chants Love at the Bound of This World', 'Yu-No: A Girl Who Chants Love at the Bound of this World is a Japanese visual novel/ point-and-click adventure game developed originally as an adult game. The game''s protagonist travels between various parallel worlds in order to solve the mystery of his parents'' disappearance. Although parallel worlds are not an unfamiliar concept in science fiction, the game uses concepts from physics, mathematics, philosophy, history and religion to construct a unique fictional universe. In particular, the A.D.M.S. or Auto Diverge Mapping System; which visually displays the branching parallel worlds/storylines as a tree, aids the player in navigation.' FROM games WHERE igdb_id = 201228 ON CONFLICT (game_id, language_code) DO NOTHING;
