INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Devil Summoner: Soul Hackers - Akuma Zensho', 'Supplementary content to Devil Summoner: Soul Hackers in the vein of the previous Akuma Zensho release for the original Devil Summoner. Players can view high quality artwork, stats and backstory of the 300+ demons found in Soul Hackers. Two new modes have been added, including a visual novel segment taking place before the game and a music mode in which a Jack Frost can dance to over 30 different tracks. Purchasers could also send in a form to Atlus in order to receive the extra dungeon disc to the original Soul Hackers game.' FROM games WHERE igdb_id = 145852 ON CONFLICT (game_id, language_code) DO NOTHING;
