INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lenny Loosejocks Goes Walkabout', 'Lenny Loosejocks Goes Walkabout is a top-down adventure game set in a fictional Australian town. Players control Lenny Loosejocks as they explore locations and complete various mini-games to unlock codes and progress. Originally a 1997 Flash game, it was re-released in 2021 for modern platforms. The game includes several distinct mini-games and features simple graphics and gameplay focused on exploration and puzzle-solving.' FROM games WHERE igdb_id = 170548 ON CONFLICT (game_id, language_code) DO NOTHING;
