INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Streets of SimCity', 'Streets of SimCity is a 1997 racing and vehicular combat computer game published by Maxis. The game offers several different modes of play, including a career mode, where the primary, mission-based play mode allows the player takes part in one of four television shows, with missions being presented as "episodes." There are four different shows to choose from, each with a set of episodes that increase in difficulty.
