INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fighting Network Rings', 'The hard hitting fighting league led by Akira Maeda Martial Arts. You know it from the broadcast on WOWOW, and is characterized by techniques and groundwork. A Realistic fighting game which all the real name combatants have taken part and motion captured the movements for the player to control!' FROM games WHERE igdb_id = 44825 ON CONFLICT (game_id, language_code) DO NOTHING;
