INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('bug-riders-the-race-of-kings', 45041, '1997-12-04', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3ur8.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2b4m.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bug Riders: The Race of Kings', 'The King of Entymion, Leptus, is about to die. Rather than hold elections or keep the tradition of primogeniture, the next king will be chosen with a race. Not just any race, but a race in which the participants ride on giant bugs. Choose from 22 different contestants, each with unique racing styles and weapon, and try to be the first to the finish line on six tracks. If finishing first is a little too tough, make your bug go faster by using your riding crop. But be careful, or your bug will quit running for you. For those looking for a less-than-honest way to win, collect power-ups and weapons scattered throughout the track to blow past your opponents or blast them out of the sky. And don''t forget to keep your eyes open for the shortcuts in each track. Do you have the nerve and the skill to win the Great Race? Play BUG RIDERS: The Race of Kings and find out.' FROM games WHERE igdb_id = 45041 ON CONFLICT (game_id, language_code) DO NOTHING;
