INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'International Superstar Soccer Pro 98', 'International Superstar Soccer Pro 98, officially abbreviated as ISS Pro 98, is a football simulation game developed and published by Konami for the PlayStation in 1997. It is part of the International Superstar Soccer (ISS) series, known for its focus on realistic gameplay and detailed graphics for the time. ISS Pro 98 features a wide range of national teams, realistic player animations, and improved AI, making it one of the more advanced football games of its era.
