INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SubSpace', 'SubSpace is a 2D space shooter game released by Virgin Interactive Entertainment (VIE) in 1997. When VIE was sold to Electronic Arts in 1998, the SubSpace license was not part of the deal, and consequently its official servers were shut down. However, some fans continued to play the game by self-hosting their own servers.' FROM games WHERE igdb_id = 19148 ON CONFLICT (game_id, language_code) DO NOTHING;
