INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Oil Panic', 'Bowser is dropping oil into a castle, and Mario must use two buckets to catch the oil before it touches the floor. Yoshi serves to dispense oil and can even be used to take out Bowser from the top of the castle, gaining bonus points in the process. In Classic Mode, the Station Helper must collect oil dripping from the ceiling of a gas station in one bucket and dump it to his boss before the bucket overflows.' FROM games WHERE igdb_id = 231724 ON CONFLICT (game_id, language_code) DO NOTHING;
