INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Putt-Putt Travels Through Time', 'In this Junior Adventure, Putt-Putt must travel through time to rescue his dog Pep and retrieve his lunchbox, calculator, and history report. This was the first Putt-Putt game to have multiple paths — the missing objects could be in one of four locations, meaning there could be different puzzles on different playthroughs.' FROM games WHERE igdb_id = 3737 ON CONFLICT (game_id, language_code) DO NOTHING;
