INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hunting', 'Hunting is a Russian amateur DOS game, found online in 2022, where players shoot alien-invading rabbits using five different weapons. It features a first-person perspective, individual kill animations, and dynamic music. Ammo is limited, and the gameplay ends when it''s depleted. The game is notably violent.' FROM games WHERE igdb_id = 341953 ON CONFLICT (game_id, language_code) DO NOTHING;
