INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Carnage Heart EZ: Easy Zapping', 'A mecha action-strategy game from Artdink. Carnage Heart EZ is an updated version of the Carnage Heart. Many of the OKEs have been rebalanced, and new features have been added including the ability to load programs from other save files (including from the original title). The difficulty of the campaign has also been increased for expert players.' FROM games WHERE igdb_id = 66184 ON CONFLICT (game_id, language_code) DO NOTHING;
