INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mega Man X4', 'Battle armies of Maverick Reploid Robots while mastering all-new strategic moves like the Air Hover and Zero''s Saber Tactic system. Discover a myriad of power-ups, secret rooms, extra weapons and invincible vehicles to take on 8 all new X-Hunter Bosses. And for the first time, play as Mega Man X or battle with his mighty partner Zero in 2 separate adventures. Mega Man X4 - now you can be a hero, or a Zero!' FROM games WHERE igdb_id = 1744 ON CONFLICT (game_id, language_code) DO NOTHING;
