INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Temujin', 'Temüjin is a first-person adventure game, notable for its use of live-action full motion video and 360-degrees movement. The player begins in the lobby of the Stevenson Museum without any clue as to how they got there or their identity. The player travel through the halls, controlled in 360-degrees movement and will encounter items, which can be picked up and manipulated as well as different people who can be interacted with in various fashions. Various puzzles relating to the Mongols and the exhibits must be solved, over seven episodes, in order to complete the game.' FROM games WHERE igdb_id = 8184 ON CONFLICT (game_id, language_code) DO NOTHING;
