INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Theme Hospital', 'Theme Hospital is a business simulation game developed by Bullfrog Productions and published by Electronic Arts in 1997, in which the player designs and operates a hospital. Like most of Bullfrog''s games, Theme Hospital is permeated by an eccentric sense of humour. The game is the thematic successor to Theme Park, a game also produced by Bullfrog. The game was a massive commercial success, selling over 4 million copies worldwide.' FROM games WHERE igdb_id = 1624 ON CONFLICT (game_id, language_code) DO NOTHING;
