INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Snow Board Championship', 'Snowboard Championship is a 2D arcade snowboarding game on courses with gameplay similar to Zigurat''s World Rally games. Using a side-scrolling bird''s-eye view the snowboarder moves forward automatically and the player has to react quickly to turns and obstacles as signalled by arrows. There are three riders to choose from, representing Europe, Japan and USA, and several courses player either in the Beginner of the Championship mode.
