INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fantastic Four', 'The Fantastic Four video game, released in 1997 for the PlayStation, is a beat ''em-up action game based on the Marvel Comics superhero team. Developed by Probe Entertainment and published by Acclaim Entertainment, the game features playable characters Mr. Fantastic, The Invisible Woman, The Human Torch, The Thing, and She-Hulk, each with unique abilities. A version for the Sega Saturn was planned but ultimately cancelled. Players engage in combat, solve puzzles, and navigate obstacles across various levels, drawing from the rich lore of the Fantastic Four comics.' FROM games WHERE igdb_id = 136849 ON CONFLICT (game_id, language_code) DO NOTHING;
