INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fallout: A Post Nuclear Role Playing Game', 'The Vault Dweller is tasked with exploring post-nuclear California in order to retrieve a water chip to replace the broken chip of Vault 13, their home, which they are the first person to ever leave. The player will engage in Western RPG character building and turn-based tactical combat while getting to know settlements and factions of people, mutants and ghouls through branching dialogue trees.' FROM games WHERE igdb_id = 13 ON CONFLICT (game_id, language_code) DO NOTHING;
