INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Extreme Assault', 'Set in a futuristic theater of war, Extreme Assault guides the player through six totally different operation zones, each sub-divided into multiple missions requiring the completion of a variety of exciting tasks. Objectives range from destroying all the enemy units in a given area, to rescuing hostages, defending towns, pulverizing hidden bases, and even engaging alien forces! 
