INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'BS Zelda no Densetsu: Inishie no Sekiban', 'Ancient Stone Tablets was a Japan-Only release for the Legend of Zelda: A Link to the Past. It was an add on made for Satellaview, a system that takes radio broadcasts and processes them into games live. The game came in four weekly broadcasts and made new additions to the original, such as weather, many new dungeons, and a new story.
