INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mega Man Battle & Chase', 'It''s robot mayhem at the Battle & Chase tournament! Dr. Wily is trying to take over the tournament with his army of Robot Masters, and now Mega Man has to enter to try and save the races! Choose your racer and head out on the tracks, and if you win, you''ll get to steal parts off your opponent''s cars, and eventually, you''ll race against the mad Dr. Wily himself!' FROM games WHERE igdb_id = 1731 ON CONFLICT (game_id, language_code) DO NOTHING;
