INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'F1 Racing Simulation', 'Duel for position against the world''s greatest drivers at 180 miles per hour! F1 Racing Simulation will impress even the most demanding Formula 1 fanatic! Featuring 22 drivers and all 16 tracks from the 1996 FIA Formula One Grand Prix Championship and the most comprehensive car set-up ever, F1 Racing Simulation thrusts you into the roles of Driver, Chief Engineer and Pit Crew Leader.' FROM games WHERE igdb_id = 691 ON CONFLICT (game_id, language_code) DO NOTHING;
