INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Velldeselba Senki: Tsubasa no Kunshou', 'A flight simulation shooting game set in the fictional planet Verdecelba. The main character Misaki who crashes on Verdeselba and survives the war while engaging with various people and the military. Unlike the Ace Combat series, this game emphasizes the appeal of flying slowly in the sky. You can''t crash in this game unless shot down in battle by an enemy. You can also stand still in the air.' FROM games WHERE igdb_id = 140026 ON CONFLICT (game_id, language_code) DO NOTHING;
