INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Magical Date EX: Sotsugyou Kokuhaku Daisakusen', 'Magical Date: Sotsugyo Kokuhaku Daisakusen is a skill game and dating sim published by Taito in 1997, as an updated version of Magical Date: Dokidoki Kokuhaku Daisakusen. In this game, the player picks one of three possible girls to date and then starts off in a square as in a board game, proceeding to other squares which have different mini games. At junction points the player is asked questions about their date and has to pick the correct answer, or she will become upset
