INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Age of Empires', 'Age of Empires (AoE) is a history-based real-time strategy video game developed by Ensemble Studios and published by Microsoft. The game uses the Genie, a 2D sprite-based game engine. The game allows the user to act as the leader of an ancient civilization by advancing it through four ages (the Stone, Tool, Bronze, and Iron Ages), gaining access to new and improved units with each advance.' FROM games WHERE igdb_id = 289 ON CONFLICT (game_id, language_code) DO NOTHING;
