INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lifescape 2: Bodybionics', 'Advanced computer technology has created cyber space that exists a model of the anthropoid body that was meant to be used for medical experiments. Although, the human body specimen has gone haywire since an accident has taken place, and a specialist has been sent in to fix the root of the issue.' FROM games WHERE igdb_id = 351552 ON CONFLICT (game_id, language_code) DO NOTHING;
