INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('shivers-ii-harvest-of-souls', 50207, '1997-04-09', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7a60.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/aruv2.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shivers II: Harvest of Souls', 'Your friends of the rock band Trip Cyclone win the Battle of the Bands and decide to make video clips in the secluded desert town of Cyclone, Arizona, located amidst the red rocks of Devil''s Mouth Canyon. They stay at the house of aunt Pearl and help her out part-time in her cafe. The town seems to have gotten stuck in time decades ago, people are strange and not welcoming to outsiders. When two hikers do not return from their trip in the canyon, on which people believe an ancient Indian curse rests, the villagers set out for a search expedition, only to lose a local villager in the process. The town is restless, tourists stop coming and the band believes they may not be able to make their rock videos, lacking the money to buy equipment. Then they are approached by a strange man wearing a traditional Indian Kachina mask, who names himself Darkcloud.
