INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tibia', 'One of the earliest and most successful massively multiplayer online role-playing games (MMORPGs) in history, Tibia is a two-dimensional tile-based game set in a fantasy world with pixel art graphics and a top-down perspective. There are currently 68 game servers online, of which 24 in Europe, 25 in North America, and 19 in South America.' FROM games WHERE igdb_id = 9596 ON CONFLICT (game_id, language_code) DO NOTHING;
