INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('cotton-2-magical-night-dreams', 39489, '1997-02-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6iqd.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/km7qbdj2azscwh8bbdg5.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cotton 2: Magical Night Dreams', 'Released first as an arcade game on Sega''s ST-V hardware in 1997. Only months later, it received a virtually arcade-perfect console port on the Sega Saturn. Considered the true sequel to the first game in the series, Cotton 2 also marks the introduction of two new primary characters: Appli, a young princess, and her anthropomorphic hat, Needle. Cotton 2 sees a return to traditional horizontal scrolling in the series, but it also stands out among shoot ''em ups in general for its unique gameplay system. With a heavy incorporation of Newtonian physics, Cotton 2 ultimately mixes elements of 2D platformers with traditional shoot ''em up gameplay. The first release of Cotton 2 on the Sega Saturn also included a mini-calendar for 1998.' FROM games WHERE igdb_id = 39489 ON CONFLICT (game_id, language_code) DO NOTHING;
