INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Great Adventures by Fisher-Price: Wild Western Town', 'Become a sheriff''s deputy and hunt down the stolen gold bars hidden by Bandit Bob across a series of wild-west themed scenes and minigames. Boot barrels at bandits, build custom wanted posters, run the general store, or fire assorted objects from canons, and experience life in Fisher Price''s Wild Western Town.' FROM games WHERE igdb_id = 205163 ON CONFLICT (game_id, language_code) DO NOTHING;
