INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Paro Wars', 'A turn-based strategy game produced by Konami in 1997 in Japan only. It features characters and conflicts based upon the popular Parodius series of video games which in turn is a parody of the long running Gradius series. It is the sixth installment of the Parodius series and is the Parodius equivalent to Cosmic Wars, a turn-based strategy game set in the Gradius universe, or R-Type Tactics, set in the R-Type universe.' FROM games WHERE igdb_id = 37305 ON CONFLICT (game_id, language_code) DO NOTHING;
