INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Robot Taisen F', 'Famous franchise of Banpresto, Super Robot Taisen is a mixture of famous Anime and Manga robots in the same universe, creating a lot of impossible situations like using a Gundam to fight against Mazinger and so on! This version is special because you have a lot of Gundam robots specially from Gundam Wing with Duo Maxwell and Heero and the famous Gainax robots from Evangelion.' FROM games WHERE igdb_id = 46667 ON CONFLICT (game_id, language_code) DO NOTHING;
