INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gambys', 'Gambys is a 1997 ecological-themed Portuguese puzzle video game for MS-DOS developed by Viagem Interactive. Utilizing 3D pre-rendered graphics for its visuals and cutscenes, it was one of the first fully Portuguese-developed games for IBM PC compatibles. Featuring a story about creatures and man, the game was environmentally themed and featured several photos of animals and scenery in its gameplay' FROM games WHERE igdb_id = 358522 ON CONFLICT (game_id, language_code) DO NOTHING;
