INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Redneck Rampage', 'Well, we crash-landed that UFO in the desert and Bubba says he wants to go home. Heck, I don''t blame him ''cause there ain''t no place like Hickston. But according to my map, we''re gonna have to blast our way through jack o'' lope farms and a riverboat as well as a brothel ''fore we get home again.' FROM games WHERE igdb_id = 9002 ON CONFLICT (game_id, language_code) DO NOTHING;
