INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'War Wind II: Human Onslaught', 'War Wind: Human Onslaught offers a great variety of vehicular, mechanised and special units, with intense and exciting maps, and a rich array of options, graphics and sounds, along with a combat model that offers a dynamic balance of play. All this, plus the addition of the human element make War Wind: Human Onslaught a compelling must-play for any real-time strategy fan.' FROM games WHERE igdb_id = 51780 ON CONFLICT (game_id, language_code) DO NOTHING;
