INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Raiden Fighters 2: Operation Hell Dive', 'Raiden Fighters 2 takes place four years after the events of the first game. In the aftermath, a few surviving guerrilla groups gather under a dictator. Together, this rogue group forms a new nation and launches a salvo of attacks on the protagonist fighting forces. In response to these surprise attacks, the government recalls the previous troops into action once again, outfitted with retooled ordinances.' FROM games WHERE igdb_id = 8859 ON CONFLICT (game_id, language_code) DO NOTHING;
