INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Su-27 Flanker Mission Disk', 'Su-27 Flanker Mission Disk expands the original Soviet fighter simulation with multiplayer capabilities supporting up to 16 players via LAN, Kali, and Kahn networks. The expansion updates the game to version 1.5, introducing refined enemy AI behavior in air combat scenarios and adds 150 new missions created with the game''s mission editor. The base game provides detailed flight controls and aerodynamic modeling of the Su-27 Flanker, offering players a simulation focused on the rarely-featured Russian combat aircraft.' FROM games WHERE igdb_id = 74051 ON CONFLICT (game_id, language_code) DO NOTHING;
