INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Monkey Shines', 'Monkey Shines is a platform game for the Apple Macintosh that was created and published as shareware by FantaSoft, LLC in 1997. In the game, a monkey named Bonzo explores various stages, gathering fruits and keys. Monkey Shines was named the most nostalgic game of the year by MacUser magazine in 1997. Later, a Microsoft Windows-compatible version of the game was created.' FROM games WHERE igdb_id = 80849 ON CONFLICT (game_id, language_code) DO NOTHING;
