INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Osmar: A Primeira Fatia do Pão-de-fôrma', 'Have you ever thought about how the first slice of bread feels? That''s right, the one nobody eats, the one they always leave aside! That''s what you''ll discover in this exciting story: Osmar, the first slice of bread, and his friend Cookie are on a mission to find the box of candies.' FROM games WHERE igdb_id = 296112 ON CONFLICT (game_id, language_code) DO NOTHING;
