INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'World Tour Racing', 'World Tour Racing was the first racer available for the Atari Jaguar CD. Earlier cartridge games, like Super Burnout and Checkered Flag were received with mixed reviews, which created some excitement for the release of WTR. Gameplay includes customizable cars, seven different racing views, and surprisingly intelligent AI. World Tour Racing also features a damage system -- too many mid-race collisions will force drivers to the pits.' FROM games WHERE igdb_id = 46923 ON CONFLICT (game_id, language_code) DO NOTHING;
