INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Last Imperial Prince', 'When an army of monsters attacked the castle Camelot and forced the Emperor to resign, the whole country fell under their rule, and the Emperor''s son Radius had to flee. But in his heart, the young prince still hopes to reclaim the land that is rightfully his, and to defeat the monstrous conquerors. With the aid of his best friend, the wandering monk Nova, and a female fighter Mirion, Radius begins his quest.' FROM games WHERE igdb_id = 45956 ON CONFLICT (game_id, language_code) DO NOTHING;
