INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sesame Street: Search & Learn Adventures', 'The Amazing Mumford tries to create a magic picnic basket to hold everything Elmo and friends need to go to the beach. He accidentally ends up teleporting all of the items across Sesame Street instead. The famous detective Sherlock Hemlock volunteers to track down the items along with your help. This is done by solving puzzles and playing educational minigames focused around shapes, matching, recycling, and more.' FROM games WHERE igdb_id = 245537 ON CONFLICT (game_id, language_code) DO NOTHING;
