INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bounty Sword First', 'Bounty Sword is a tactical strategy role-playing game set in a fictional futuristic world with a power struggle looming between Europea and the Kingdom of Rheinmetall. The game puts heavy focus on battle mode and offers a detailed tutorial one can go through before starting the story mode. During the battle your character can use close-combat weapons such as sword, initiate special devastating attacks, or use magic and items either to combat or as a remedy.' FROM games WHERE igdb_id = 57059 ON CONFLICT (game_id, language_code) DO NOTHING;
