INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sanrio Uranai Party', 'Sanrio Uranai Party is a fortune-telling game for Nintendo''s Game Boy series of gaming consoles. The player can choose to either have their fortune told (money, love, health, general) or they can do a compatibility check between one person and another person in friendship or love. The player must enter their date of birth, gender and blood type before getting their fortune told.' FROM games WHERE igdb_id = 97414 ON CONFLICT (game_id, language_code) DO NOTHING;
