INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rabbit', 'Rabbit is a 2D fighting game, with cartoonish colorful graphics. The game has 8 playable characters - Wu Ling (Rabbit), Tien-Ren (hawk), Eight (ox), Hou-En (wolf), Ja-Koh (snake), Yu-Lan (fox), Rex (tiger) and Eddy (wild boar). The player chooses one from these heroes, and must defeat all opponents, plus the final boss.
