INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NFL Quarterback Club 98', 'Do you have the courage to be an NFL quarterback? The same folks that brought you TUROK have turned their attentions to the gridiron and have brought great graphics, realistic action, and lots of options to the sport. With full licenses from the NFL and its athletes, the game has all of the teams and players, plus perfect replications of logos and stadiums. Just to assure that the artificial intelligence was high and the gameplay realistic, the developers coaxed Brett Favre into designing some of the plays.' FROM games WHERE igdb_id = 3558 ON CONFLICT (game_id, language_code) DO NOTHING;
