INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'AHx-1', 'An authentic simulation of one of the world''s most versatile and deadly attack helicopters, AHx-1 puts players behind the wheel of an AHx-1 Viper. The game offers 45 simulated combat missions and thirty life-like scenarios to tackle that take place in exotic enemy territory such as Columbia and Libya. Authenticity is the focus of this game designed by ex-Israeli fighter pilots to mimic actual combat.' FROM games WHERE igdb_id = 64918 ON CONFLICT (game_id, language_code) DO NOTHING;
