INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Get Lost!', 'Attempt to find exits in mazes in this first person 3d maze game from Tom Bombadil''s Software Emporium & House of Curiosities. Explore over 50 unique mazes. Replay completed mazes if desired. Difficulty for each maze varies. Some mazes require that the player touch certain spaces to find the exit. Others require taking certain paths in sequence.' FROM games WHERE igdb_id = 50252 ON CONFLICT (game_id, language_code) DO NOTHING;
