INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fox Sports Golf ''99', 'Fox Sports Golf 99 features six 3D courses for up to four players to compete on: Forest Downs, Orange Rock, Sunny Green Country Club, Kiawah Island (site of the 1997 World Cup of Golf), Oxfordshire in England (Benson & Hedges International Open), and Carnoustie Golf Links (home of the 1999 British Open). Players can also practice their pitching and putting techniques or work on their long game by having a whack at the driving range. A traditional triple click interface is used to execute each shot, and two commentators will call the action as you progress through the links: choose legendary announcer Peter Allis, Fox Sports Net''s John Walls, or have both analyzing your game.' FROM games WHERE igdb_id = 44941 ON CONFLICT (game_id, language_code) DO NOTHING;
