INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nightmare Circus', 'On opening night, the circus was set ablaze and burned completely to the ground by its shady and villainous operator, the Jester, who intended to cash in on an insurance policy. Afterwards, the Jester was convicted for the deaths of the fire victims, but before he was executed, the Jester warned that the souls of the victims would be forever tormented. Many years later, a Native American man named Raven who had lost relatives to the fire goes to investigate the site where the circus was held, and where strange happenings have been reported.' FROM games WHERE igdb_id = 46177 ON CONFLICT (game_id, language_code) DO NOTHING;
