INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dragon''s Dream', 'Dragon''s Dream (ドラゴンズドリーム) is a Sega Saturn Online RPG released exclusively in Japan. It was distributed in very low numbers for free in order to promote the Saturn''s online capabilities in Japan. Sega had planned a PC version, but this never materialised. For a short time, there were also mentions of the XBAND version.' FROM games WHERE igdb_id = 268638 ON CONFLICT (game_id, language_code) DO NOTHING;
