INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lineality', 'Are you sick of all those 3D games on the market? Try Lineality, the worlds first one dimensional action shooter game. Sounds low-tech? Not at all. Your one-dimensional battlefield can rotate in three dimensions as you play! A parody of any game that ever put technology ahead of playability!' FROM games WHERE igdb_id = 286600 ON CONFLICT (game_id, language_code) DO NOTHING;
