INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rabid Helix', 'In this game, you are the medic of a corporate security team in some sci-fi setting sent to investigate a long-abandoned research installation owned by the company''s predecessor. Similar to the lieutenant of the Colonial Marines in Aliens, you sit behind a bank of monitors and observe your teammates'' status as they investigate the interior of this compound. And like Aliens, something nasty is waiting for them inside.' FROM games WHERE igdb_id = 257656 ON CONFLICT (game_id, language_code) DO NOTHING;
