INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mean City: Learn English or Die!', 'Mean City is an interactive adventure game in which the player has 10 hours to save Harry, a television reporter you meet in the beginning of the game. Mean City is being terrorized by an evildoer, the Jinx, and you have to find out why and stop him by interacting with various characters - in english of course.
