INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'F-22 Air Dominance Fighter', 'F-22 Air Dominance Fighter is a military flight simulation that recreates the experience of piloting America''s advanced fighter aircraft. The game features 20 training missions, including takeoffs, landings, mid-air refueling, and combat scenarios, alongside three campaign tours set across the Red Sea, Eritrea, and Saudi Arabia. Players engage in missions using authentic avionics and weapon systems while navigating diverse terrain from deserts to valleys.' FROM games WHERE igdb_id = 693 ON CONFLICT (game_id, language_code) DO NOTHING;
