INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wing Commander: Prophecy', 'Wing Commander: Prophecy, the fifth installment in the acclaimed space combat series, introduces a new generation of pilots in a post-war galaxy. Players assume the role of rookie Lance Casey aboard the TCS Midway, facing an unexpected alien threat foretold by ancient Kilrathi prophecy. Set against the backdrop of a fragile peace following the Border Worlds conflict, the game combines intense space combat with late 90s FMV storytelling. Pilots engage in dangerous missions, wielding an arsenal of advanced weaponry to defend the Confederation against a mysterious force that threatens the universe''s existence.' FROM games WHERE igdb_id = 935 ON CONFLICT (game_id, language_code) DO NOTHING;
