INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Casper', 'Casper is a game developed by Absolute Entertainment and published by Natsume for the Super NES. The player controls Casper who is followed by Kat Harvey, and he has to protect her from any danger. Being a ghost, Casper can pass through walls and other obstacles, unlike in most Casper games, but he can''t go away from Kat too much or else Carrigan''s ghost will abduct her. The game follows loosely the plot of the movie. This game uses a revised Absolute A Boy and His Blob engine. Picking up special objects allows Casper to morph into these objects to clear rooms of enemies, and to protect Kat from certain hazards. Mirrors placed throughout the game allows Casper and Kat travel to other parts of mansion, and outside electrical lines allow Casper to pick up the last of the toys when he picks up the electric bolt morph.' FROM games WHERE igdb_id = 215184 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_companies (game_id, company_id, role, is_primary) SELECT g.id, c.id, 'developer', false FROM games g, companies c WHERE g.igdb_id = 215184 AND c.slug = 'absolute-entertainment' ON CONFLICT DO NOTHING;
INSERT INTO game_companies (game_id, company_id, role, is_primary) SELECT g.id, c.id, 'developer', false FROM games g, companies c WHERE g.igdb_id = 215184 AND c.slug = 'natsume-inc' ON CONFLICT DO NOTHING;
