INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Monster Palace', 'Monster Palace is a video game for Windows 95 developed by Clementoni, an Italian toy company. This game falls under the horror genre aimed primarily at children and features a limited release in Italy. However, it was never translated into other languages, making it predominantly available in Italian. The game involves navigating a haunted mansion filled with puzzles and a mysterious atmosphere, where players use tools like tarot cards, crystal balls, and pendulums to solve puzzles.' FROM games WHERE igdb_id = 324745 ON CONFLICT (game_id, language_code) DO NOTHING;
