INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pacific General', 'Pacific General is a simulation game set in the Pacific theater of conflict in World War II, pitting the Japanese Empire against the combined might of the Allied forces. In this game, it is possible to take either side in the conflict, which can be played from the dawn of combat in 1937 through to the historical or hypothetical outcome(s) of the war. Land, air, and naval operations play a key role in the battles to be fought.' FROM games WHERE igdb_id = 14451 ON CONFLICT (game_id, language_code) DO NOTHING;
