INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Formula Karts', 'Formula Karts is a semi-realistic racing title that attempts to capture the spirit of kart racing with it''s low slung feeling of speed, and corner after corner of impressive handling (and inevitable sliding). The title supports both simulation and arcade modes, and features some effective race AI for non-player vehicles. Two player split screen is supported albeit with some slowdown.' FROM games WHERE igdb_id = 319112 ON CONFLICT (game_id, language_code) DO NOTHING;
