INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Paparazi', 'How would you like to be pursued relentlessly with no recourse -- chased without the ability to elude your stalkers? If your answer to this question is "yes" then we think you need serious counseling. Want to "test the waters" and get some idea of what it is like? Download Paparazi and find out for yourself!' FROM games WHERE igdb_id = 272503 ON CONFLICT (game_id, language_code) DO NOTHING;
