INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Evolution: The Game of Intelligent Life', 'Evolution: The Game of Intelligent Life is a life simulation and real-time strategy computer game that allows players to experience, guide, and control evolution from an isometric view on either historical earth or on randomly generated worlds while racing against computer opponents to reach the top of the evolution chain, and gradually evolving the player''s animals to reach the "grand goal of intelligent life".' FROM games WHERE igdb_id = 37049 ON CONFLICT (game_id, language_code) DO NOTHING;
