INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mortalus: The Quest for Immortality', 'An exciting role-playing action game from the maker of UFOs, Celtica, and Gems of Darkness, Mortalus takes players into a three-dimensional world of medieval adventures. Can you find the source of immortality or will you fall slain to the Servants of the Hand? Will your hunt lead you to the curse of the Dark Brotherhood or will you triumph in the powers held within the Book of Dark Knowledge?' FROM games WHERE igdb_id = 145423 ON CONFLICT (game_id, language_code) DO NOTHING;
