INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Solar Assault', 'Solar Assault is a 1997 Konami arcade shoot ’em up and a 3D spinoff of the Gradius series. Using a flight-sim style cockpit cabinet, players pilot Vic Viper through fully 3D environments while retaining classic Gradius mechanics like power-up bars and iconic enemies. Despite its impressive visuals and unique perspective, the game was never widely released outside Japan and remains one of the more obscure entries in the Gradius franchise.' FROM games WHERE igdb_id = 1485 ON CONFLICT (game_id, language_code) DO NOTHING;
