INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MK5 Mortal Kombat: Sub-Zero', 'MK5 Mortal Combat - Sub-Zero is a bootleg for the Sega Mega Drive and Sega Genesis consoles, published between 1997 and 1998, being distributed in an independent cartridge format. There is also a little known and difficult to find port of this same video game for the Super Nintendo / Super Famicom console, called Mortal Kombat Mythologies Gold 2000.' FROM games WHERE igdb_id = 155515 ON CONFLICT (game_id, language_code) DO NOTHING;
