INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sítio do Picapau Amarelo: Caçadas de Pedrinho', 'In Caçadas de Pedrinho, players join Pedrinho, Narizinho, Emília, and other characters from Monteiro Lobato''s Sítio do Picapau Amarelo in an adventure to hunt a jaguar that threatens the Sítio. The game features animated screens where players can explore the Sítio, forest, and its inhabitants, interacting with the story by reading, listening, and completing challenges. Activities include testing aim, solving mazes, challenging memory, coloring characters, assembling puzzles, and navigating mini-games with adjustable difficulty. With 256-color graphics and interactive elements, the game combines learning, action, and fun in a detailed, animated environment.' FROM games WHERE igdb_id = 286934 ON CONFLICT (game_id, language_code) DO NOTHING;
