INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Lost World: Jurassic Park', 'The Game Gear received a unique adaptation of the 1997 dinosaur sequel The Lost World: Jurassic Park. It is primarily a side-scrolling platform game but also includes some other gameplay elements. Players control a hunter who, armed with a stun rifle and having enlisted the help of a friendly Procompsognathus ("Compy"), must make his way through various levels on Isla Sorna to finally reach a helicopter and escape.' FROM games WHERE igdb_id = 147442 ON CONFLICT (game_id, language_code) DO NOTHING;
