INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dark Angael', 'Dark Angael is a 2D run-and-gun platform game with a mystical fantasy theme. In this game you play as Carina, the Dark Angael. Thanks to Azrael the world has been plunged in total chaos and the end is near. It is up to you to defeat Azrael and his army of demons. Carina has to fend off the demon''s with the various weapons she finds or she can rely on her superpowers.' FROM games WHERE igdb_id = 206964 ON CONFLICT (game_id, language_code) DO NOTHING;
