INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NFL 98', 'NFL 98 (also known as NFL Prime Time 98) is a sports video game released for the Sega Genesis in 1997. Based on the National Football League, the game was a follow up to Sega''s only football video game for the Sega Saturn, NFL ''97. It is the last game in Sega''s original Joe Montana/NFL series, which would be succeeded by NFL 2K.' FROM games WHERE igdb_id = 126091 ON CONFLICT (game_id, language_code) DO NOTHING;
