INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'JumpStart Adventures 5th Grade: Jo Hammet, Kid Detective', 'JumpStart Adventures 5th Grade tells about a kid named Jo Hammet, Kid Detective. When the city of Hoverville has electric problems from the evil Dr. X, Jo goes out to stop him. Go to several stores and places in Hoverville asking the owners for help. If you help them with puzzles, they''ll give you something you may need to stop Dr. X. In the meantime try spying on three octopus-haired men!' FROM games WHERE igdb_id = 71317 ON CONFLICT (game_id, language_code) DO NOTHING;
