INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Assault Trooper', 'Assault Trooper is an isometric stealth shooter that sends you to perform fifty missions in many exotic locations, such as Libya, North Korea, Afghanistan, and so on. At the beginning of the game you get to choose from only a few different missions in each location, but completing them will open new ones. The objectives vary from, for example, assassinating enemy officers to stealing important documents or rescuing hostages.' FROM games WHERE igdb_id = 47021 ON CONFLICT (game_id, language_code) DO NOTHING;
