INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('anastasia-adventures-with-pooka-and-bartok', 69561, '1997-11-25', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1l98.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc6k1e.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Anastasia: Adventures with Pooka and Bartok', 'Anastasia must overcome obstacles and the demonic servitors of Rasputin in an attempt to escape from Russia and find her parents. As Pooka, her dog, you assist her while eluding Bartok''s traps, solving puzzles and gathering information that Bartok, the irascible talking bat, lets slip as he cheers on the minions who are trying to catch you. The five locations in the adventure include St. Petersburg, a palace, a train, a ship and Paris. In each place, Pooka has a specific task that will help Anya reach her goal, ranging from contacts with Dmitri to creating passports and helping a Prima Ballerina find her lucky ballet slippers. Throughout the journey, you must also avoid Rasputin''s minions who will zap Pooka into the underworld and make him play deadly games to escape. While underground, Pooka is challenged to several games including Doggy Dodge (dodge rocks), Minion Mosh (a jumping game similar to Fox and Geese), Skull Toss (bowling-like game using Rasputin''s denizens as targets) and Hidden Maze. In the latter, you see a maze for a short time and then try and guide Pooka safely through to the other side. Between locations, you hear entries from Anya''s diary and after the game is completed, you''re rewarded with screenshots from the movie. Anastasia''s voiceover features actress Meg Ryan who had the same role in the animated movie. Can you help Anya find out who her parents are and escape the clutches of Rasputin? Find out, in Anastasia: Adventures with Pooka and Bartok.' FROM games WHERE igdb_id = 69561 ON CONFLICT (game_id, language_code) DO NOTHING;
