INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blackout', 'Blackout is a Danish psychological horror adventure game, created and produced by Michael Valeur and Deadline Games and released in 1997. The game uses stop-motion FMV sequences with puppets to deliver a story about an amnesiac protagonist in the backstreets of Copenhagen, Denmark. Walking the streets of Copenhagen, the protagonist runs into many shady characters, some of whom seem to have additional information on who the character is. The game features a mystery based on multiple personalities being uncovered by a psychologist, assassinations, prostitution, and the production of snuff porn. The game came with a companion novel, written by Michael Valeur.' FROM games WHERE igdb_id = 221817 ON CONFLICT (game_id, language_code) DO NOTHING;
