INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('zork-the-undiscovered-underground', 1954, '1997-08-28', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2mu7.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zork: The Undiscovered Underground', 'The purpose of the game is to explore and emerge successfully from the Undiscovered Underground. The player begins only with a low-quality Lantern and plastic imitation sword, a parody of the starting items from Zorks I, II and III. Upon entering the Undiscovered Underground, the adventurer is trapped by a freak avalanche. The only way to escape is to release the mutant Rat Ants (an echo from Starcross) and to direct them to the avalanche, which they dispatch in a manner reminiscent of Aesop''s Fables. The player must demask the Grue vendor to gain the four candy bars and place the relevant objects in the Mud Forum on the appropriate corresponding floor symbols. This unleashes a mutant chase reminiscent of Planetfall where the adventurer stays one step ahead of the Rat Ants because of the shrewdly placed candy bars. However, the escape comes at the cost of unleashing a Rat Ant epidemic onto the empire and forces the adventurer to flee from the wrath of the Grand Inquisitor.' FROM games WHERE igdb_id = 1954 ON CONFLICT (game_id, language_code) DO NOTHING;
