INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Touhou Yumejikuu: Phantasmagoria of Dim. Dream', 'This game is a vertical danmaku shooting game, where two characters engage in danmaku gameplay within individual and separate play areas (aka. split-screen). Upon meeting certain conditions, players are able to unleash a variety of character-specific Spell Attacks upon their opponents in an attempt to whittle down their remaining health points.
