INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Universal Nuts', 'Universal Nuts is a sci-fi visual novel featuring two protagonists, Yui and Ai, which get involved in an incident onboard a space station. As the story progresses, the mystery of events that have occurred start to unfold. The game plays in a typical visual novel style by reading through on-screen text and dialogues to progress the story. Character icons are present during dialogues beside the character art over the background image, and the game features both animated cut-scenes and voice-acting.' FROM games WHERE igdb_id = 91955 ON CONFLICT (game_id, language_code) DO NOTHING;
