INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'S40 Racing', 'S40 Racing is a promotional game for the Volvo S40. It lets you drive the S40 over two courses against either the AI opposition or friends over a LAN. Two game modes are available: a standard race where you race against seven opponents, and time attack where you have the race course for yourself. For each race you can set up whether you want manual transmission or not & how many laps the race should have, from one to twenty.' FROM games WHERE igdb_id = 93213 ON CONFLICT (game_id, language_code) DO NOTHING;
