INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'D.A.: Pursuit of Justice - The Rat Tattoo Murder', 'D.A.: Pursuit of Justice - The Rat Tattoo Murder is a law simulation game where players assume the role of an Assistant District Attorney in California. The case involves investigating the murder of Tommy Wu following a confrontation between rival gangs at a pool hall, determining whether his death was accidental or premeditated. Players gather evidence by visiting the police station to review witness statements, examining physical evidence, and ordering lab analyses at the crime lab.
