INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'F-16 Fighting Falcon', 'F-16 Fighting Falcon aims to attract a wide audience, since the lover of an action game (with the Quick Start option) until the specialist able to explore more than nine tens gifts missions. The unit commands the player flies three war zones in air-to-air and air-to-ground, in great detail, and landscapes generated from the original maps of Korea, Israel and Cyprus.' FROM games WHERE igdb_id = 14060 ON CONFLICT (game_id, language_code) DO NOTHING;
