INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Marble Master', 'Master all four exciting modes of play: Single Player - Mission and Sudden Death, Competitive and Arcade Mode. Plus an in-depth tutorial mode that will help you become a Marble Master! Marbles with Attitude - Over 25 different kinds, Jokers, Bombs, Crushers, Color Zappers and more, each with a special Power. Infinite Gameplay! Endless hours of challenging fun. Balance is Key! Innovative scale feature adds a new puzzle challenge.' FROM games WHERE igdb_id = 2618 ON CONFLICT (game_id, language_code) DO NOTHING;
