INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fat Boy Raids The Cookie Factory', 'Fat Boy Raids The Cookie Factory is a retro-style game where players guide a cookie-craving character named Fat Boy through a series of challenging levels inside a cookie factory. The goal is to collect as many treats as possible while dodging factory guards and obstacles. With simple controls, the game combines arcade action with puzzle-solving.' FROM games WHERE igdb_id = 321865 ON CONFLICT (game_id, language_code) DO NOTHING;
