INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Off Road Challenge', 'The END of the ROAD is only the BEGINNING. Strap yourself in and get ready to ride! Players battle the elements and each other in a race that takes them across 6 rugged courses including the Mojave Desert, Las Vegas and Pike''s Peak! Choose Circuit Mode and climb your way to the top of the heap. Course terrain includes snow, water, asphalt, dirt, sand, rocks and mud. Four selectable trucks and four hidden trucks. Players can customize trucks in the Speed Shop.' FROM games WHERE igdb_id = 3567 ON CONFLICT (game_id, language_code) DO NOTHING;
