INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Live or Die', 'Live or Die is a real-time strategy game about a war battle between good and evil that takes place in the future. Mankind frantically expands into outer space and fights for the scarce energy source (uranium) on which they depend for survival. You, Dr. Whiet, leads a team of miners to land on the desolate planet of Mimas, ready to carry out a mining plan, but they are surprised to find human footprints in a valley. You are not alone. The story begins here.' FROM games WHERE igdb_id = 277238 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 277238 AND ge.slug = 'real-time-strategy-rts' ON CONFLICT DO NOTHING;
