INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Payuta and the Ice God', 'Payuta and the Ice God is an educational interactive game for children set in the Arctic. Players take on the role of Payuta, a young Inuit boy who must challenge Kiagnyk, the ice god, to rescue his kidnapped sister Opiak. Throughout the adventure, children engage with puzzles, memory challenges, and skill-based minigames that teach them about Inuit culture, traditions, and daily life in the Arctic. The game blends entertainment with learning, offering insights into Inuit lore and lifestyle while guiding players through Payuta''s quest to save his sister from the threatening ice god.' FROM games WHERE igdb_id = 325753 ON CONFLICT (game_id, language_code) DO NOTHING;
