INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('casper-the-interactive-adventure', 215183, '1997-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co98as.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scuyhi.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Casper: The Interactive Adventure', 'Casper: The Interactive Adventure is a Point and click adventure CD-ROM game made by WizardWorks and Morning Star Multimedia in 1997 and takes place after the 1995 film. After the Harvey''s go on vacation, Casper''s human friends throw him a party to cheer him up but a revived Carrigan turns them into ghosts, using a magic spell from an old book in the library, and hides them somewhere in the manor as revenge for being tricked out of the ultimate treasure. The player must use various items to travel around Whipstaff to find traces of Casper''s friends and take pictures of them for hints and collect items while defending against attacks by the Ghostly Trio who are on Carrigan''s side. There was supposed to be a sequel as stated in the ending and the manual where the player would help Casper turn his friends back into "fleshies" but Morning Star went bankrupt before it was made.' FROM games WHERE igdb_id = 215183 ON CONFLICT (game_id, language_code) DO NOTHING;
