INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'My Amazing Human Body', 'In this fantastic and funny anatomical interactive adventure, children join Seemore Skinless, a mischievous 3D skeleton, in a variety of games and activities aimed at answering commonly asked questions about the body. They''ll learn about human anatomy, health, nutrition, and much more through fun activities like "building" a body and "a day in the life" of Seemore. Beautifully presented information, engaging activities and terrific reference resources all combine to create an anatomical adventure children will return to again and again!' FROM games WHERE igdb_id = 129506 ON CONFLICT (game_id, language_code) DO NOTHING;
