INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Daytona USA Deluxe', 'Deluxe borrows most of its features from the US/PAL Championship Circuit Edition and the Japanese Circuit Edition, both Sega Saturn exclusives. However, it also adds eight-player network support and a brand new exclusive track; Silver Ocean Causeway. The original hornet from the arcade Daytona USA is also unlockable.' FROM games WHERE igdb_id = 73482 ON CONFLICT (game_id, language_code) DO NOTHING;
