INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('marble-drop', 69994, '1997-02-28', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/abjunm5xmylepzt2081v.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/m4nndzs4r5icbvrqqf6d.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Marble Drop', 'Players are given an initial set of marbles that are divided evenly into six colors: red, orange, yellow, green, blue, and purple, with two more colors available to purchase: black and silver (steel). These marbles are picked up and dropped by the players into funnels leading to a series of rails, switches, traps and other devices which grow more complex as the game progresses. The aim is to ensure that each marble arrives in the bin of the same color as the marble. Players must determine how the marble will travel through the puzzle, and how its journey will change the puzzle for the next marble. When a marble runs over certain sections of the puzzle, the paths may be rerouted or cut off, either temporarily or permanently. For example, if the marble runs over a button, it might hop, skip and jump a diversion that sends the next marble down a different road.' FROM games WHERE igdb_id = 69994 ON CONFLICT (game_id, language_code) DO NOTHING;
