INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Callahan''s Crosstime Saloon', 'Callahan''s Crosstime Saloon is a puzzle-solving adventure game based on Spider Robinson''s series of stories about the unusual patrons of Callahan''s bar. The characters in the game are taken from the first book of the series, though their stories are original. The game''s world is composed of still screens viewed from first-person perspective. The interaction is point-and-click, with context menus appearing when the player attempts to interact with an object on screen.' FROM games WHERE igdb_id = 12410 ON CONFLICT (game_id, language_code) DO NOTHING;
