INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Domino', 'Domino is a digital conversion of the classical tile laying game of Dominoes. Each rectangular tile has a number of dots on both long ends. In turns players place one of their tiles on the table. Tiles must connect to evenly numbered edges. The first player to lose all his tiles wins the game. When the player can''t place any of his tiles he has to pass.' FROM games WHERE igdb_id = 77152 ON CONFLICT (game_id, language_code) DO NOTHING;
