INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Groove on Fight', 'The story of this sequel of the series, known as Gouketsuji Ichizoku 3: Groove on Fight in Japan, takes place 20 years after the last Goketsuji tournament. It also has a darker and more serious tone than its predecessors, similar to that of Garou: Mark of the Wolves, but still maintains a little of the same humor that is particular to the series.' FROM games WHERE igdb_id = 39420 ON CONFLICT (game_id, language_code) DO NOTHING;
