INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('breakout-2000', 40816, '1997-01-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/wly5hkz53u0gob3hf98u.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scm7jo.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Breakout 2000', 'SMASH! POW! CRUNCH! Is your hand/eye coordination up to demolishing field after field of bricks? Breakout 2000 brings back the nostalgia of early gaming days but adds 90''s challenges, such as a three-dimensional field and bricks that resist breaking, as well as many powerups and hazards. You can also test your skill against a buddy. Break through your own wall and start working on his. You''ll gain bonus points, and he''ll go nuts! Who ever said life was fair never played Breakout 2000.' FROM games WHERE igdb_id = 40816 ON CONFLICT (game_id, language_code) DO NOTHING;
