INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wing of Alnam: Shouchiri no Sora no Achira he', 'Alnam no Tsubasa is a sequel to Alnam no Kiba. Like its predecessor, it is a Japanese-style role-playing game with a character-driven story, linear advancement, and simple leveling-up. Combat is turn based, with up to four player-controlled characters forming a party. Characters can attack physically, cast spells, or execute special attacks that take up a part of a corresponding gauge. Magic is learned by receiving magic points for winning battles and using them to create various spells. The game features 3D background graphics with 2D sprites representing characters.' FROM games WHERE igdb_id = 167100 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 167100 AND ge.slug = 'role-playing-rpg' ON CONFLICT DO NOTHING;
