INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Critical Blow', 'A legend exists among the fighters and martial artists of this world, of a mysterious scarab badge that only the most elite warriors will earn. This badge, sent out by the mysterious Merkuar, is in fact an invitation to a dangerous tournament held in England, where the contestants fight for money, power, and glory. Now, a poor young fighter from Hong Kong named Rickey Leon has just received one of these badges.' FROM games WHERE igdb_id = 44797 ON CONFLICT (game_id, language_code) DO NOTHING;
