INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ikusa Miko: Vestal Virgin', 'Ikusa Miko: Vestal Virgin is a simulation game released by AliceSoft. The game tasks the player, who was a vengeful demon hunter, with the growth of a warrior shrine maiden girl, after she has inherited your demon slaying powers. The game hinges on the player’s ability to foster her schedule which seeks to build her physical and mental attributes.' FROM games WHERE igdb_id = 311342 ON CONFLICT (game_id, language_code) DO NOTHING;
