INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Doraemon: Nobita to 3-tsu no Seireiseki', 'Doraemon: Nobita to Mittsu no Seireiseki is a 3D platform action game for the Nintendo 64. It was released only in Japan in 1997. The game is based on the Japanese manga Doraemon and has two Nintendo 64 sequels, Doraemon 2: Nobita to Hikari no Shinden and Doraemon 3: Nobita no Machi SOS!, both only released in Japan.' FROM games WHERE igdb_id = 70797 ON CONFLICT (game_id, language_code) DO NOTHING;
