INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'PGA Tour Pro', 'Play golf on the PGA Tour versus the computer or a friend via LAN or modem at two famous courses: "The TPC Scottsdale" and "The Bay Hill Club". You can also play with up to 80 other players on the Internet. Among the features there is Flash Draw (no waiting between shots), TV-style presentation, a 3D hole overview, a Risk meter to assess the potential risk of your next shot, the ability to walk the course in real time to read the green and view fly-bys and hear strategic commentary. There is also a Extra Disc that allows you to play Pebble Beach.' FROM games WHERE igdb_id = 94514 ON CONFLICT (game_id, language_code) DO NOTHING;
