INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'True Love Story: Remember My Heart', 'The game is largely similar to True Love Story. For each character, we increased the number of date events from two to three per season. Ordinary events have also been added, such as adding voice actors to male students and allowing them to go home with the protagonist''s younger sister Misaki. The opening movie has been changed along with the change of the theme song.' FROM games WHERE igdb_id = 166378 ON CONFLICT (game_id, language_code) DO NOTHING;
