INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Choujikuu Yousai Macross: Ai Oboete Imasu ka', 'Choujikuu Yousai Macross: Ai Oboete Imasu ka is a side-scrolling 2D shooter that ties into the Macross franchise. In the game, the player takes the control of main protagonist Hikaru Ichijyo, as he battles Zentradi units on each stage. The player has two basic attacks: Gun Pod and missiles. In addition, the VF-1 Valkyrie unit controlled by the player can transform into Fighter, Gerwalk and Battroid modes during battle.' FROM games WHERE igdb_id = 46094 ON CONFLICT (game_id, language_code) DO NOTHING;
