INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lode Runner Extra', 'Lode Runner Extra is a stand-alone expansion for Lode Runner: The Legend Returns, featuring 110 new levels for advanced players and an integrated level editor. The gameplay remains the same in this action-platformer, where the objective is to collect all the gold nuggets and bars scattered around each stage to activate a portal to the next level. Red monks chase the main character around the many platforms and ledges, killing the adventurer when finally reaching him. New tools and other helpful pieces of equipment are slowly introduced with cutscenes showing their usage.' FROM games WHERE igdb_id = 109027 ON CONFLICT (game_id, language_code) DO NOTHING;
