INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Frenetic Five vs. Sturm und Drang', 'In this game about under-powered superheroes, you play as Improv, leader of the Frenetic Five. You use common objects in surprisingly useful ways. Bob, your contact at Supertemps, hires your team for a new job: defeat the melodramatic supervillains Sturm und Drang who have holed up in the abandoned flange mill at the waterfront.' FROM games WHERE igdb_id = 217771 ON CONFLICT (game_id, language_code) DO NOTHING;
