INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Reader Rabbit Preschool', 'Reader Rabbit and Mat the Mouse take charge in this spunky preschool prep program in which the duo must scare up keys to unlock The Wonder Pony and ride the magic carousel. You''ll earn keys by playing four different games that teach basic math, shapes, colors, and listening skills. Play hide and seek learn counting forward and backward, visit the diner to whip up some banana-fish-corn casserole and become acquainted with the alphabet, or join the Pattern Parade to learn logic. There are four different skill levels, so as you get smarter, the games get harder.' FROM games WHERE igdb_id = 317113 ON CONFLICT (game_id, language_code) DO NOTHING;
