INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The DJ-ROM: Da CD-Extra of Hip-Hop Music', 'The streets of Night City are full of cool sound materials! Make songs in the studio and play them in the club. This is an electric fighting space with a Hip-Hop taste! The game world realistically portrays the life of authentic DJs with 3D graphics. Hone your heart as a DJ while experiencing various events in the city of freedom, opportunity, demonization & violence!' FROM games WHERE igdb_id = 281294 ON CONFLICT (game_id, language_code) DO NOTHING;
