INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Trek: Starfleet Academy', 'Star Trek: Starfleet Academy is a PC Star Trek simulation game that simulates the life of a typical Starfleet cadet. The object in the game is for the player to learn the basics of flying a starship so that the player can eventually become a captain of one''s very own ship.
